# The group generated by T = Toff(0;1,2) and C = CS_03 on four wires, as
# phased permutations of the 16 basis states (phases in Z/4), its order,
# the orders of short words, and which short relations hold.
from itertools import product
N = 4; DIM = 16
def toff(x): return x ^ 1 if (x >> 1) & 1 and (x >> 2) & 1 else x
# element: (perm, phase) with phase[x] in Z/4: M e_x = i^phase[x] e_perm[x]
T = (tuple(toff(x) for x in range(DIM)), tuple(0 for _ in range(DIM)))
C = (tuple(range(DIM)), tuple(1 if (x & 1) and (x >> 3) & 1 else 0 for x in range(DIM)))
def mul(a, b):   # a after b : (a b) e_x = a (i^pb e_pb) = i^pb i^pa[pb x] e_pa[pb x]
    pa, fa = a; pb, fb = b
    return (tuple(pa[pb[x]] for x in range(DIM)), tuple((fb[x] + fa[pb[x]]) % 4 for x in range(DIM)))
def inv(a):
    pa, fa = a
    pinv = [0] * DIM
    for x in range(DIM): pinv[pa[x]] = x
    return (tuple(pinv), tuple((-fa[pinv[x]]) % 4 for x in range(DIM)))
E = (tuple(range(DIM)), tuple(0 for _ in range(DIM)))
def order(a):
    k, p = 1, a
    while p != E: p = mul(p, a); k += 1
    return k
# BFS the group
gens = {'T': T, 'C': C}
seen = {E: ''}; frontier = [E]
while frontier:
    nxt = []
    for g in frontier:
        for name, h in gens.items():
            k = mul(g, h)
            if k not in seen:
                seen[k] = seen[g] + name; nxt.append(k)
    frontier = nxt
print('order of <T, C>:', len(seen))
TC = mul(T, C); CT = mul(C, T)
print('order of T, C, TC:', order(T), order(C), order(TC))
PP = mul(mul(T, C), mul(inv(T), inv(C)))
print('order of [T,C]:', order(PP), '  (TC)^2 == (CT)^2:', mul(TC, TC) == mul(CT, CT))
print('[T,C] commutes with C:', mul(PP, C) == mul(C, PP), ' with T:', mul(PP, T) == mul(T, PP))
print('T [T,C] T == [T,C]^-1:', mul(mul(T, PP), T) == inv(PP))
# the derived subgroup and the centre
center = [g for g in seen if all(mul(g, h) == mul(h, g) for h in (T, C))]
print('centre size:', len(center), 'PP^2 central:', mul(PP, PP) in center, 'PP central:', PP in center)
# the abelianisation: order / derived subgroup
comms = set()
els = list(seen)
import random
random.seed(1)
D = {E}; fr = [E]
cg = [mul(mul(a, b), mul(inv(a), inv(b))) for a in (T, C) for b in (T, C)]
# generate the normal closure of commutators
genD = set(cg)
changed = True
Dset = {E}
fr = [E]
while fr:
    nx = []
    for g in fr:
        for h in genD:
            for k in (mul(g, h), mul(g, inv(h))):
                if k not in Dset: Dset.add(k); nx.append(k)
    fr = nx
# close under conjugation by generators
while True:
    new = set()
    for g in Dset:
        for s in (T, C):
            k = mul(mul(s, g), inv(s))
            if k not in Dset: new.add(k)
    if not new: break
    Dset |= new
    fr = list(new)
    while fr:
        nx = []
        for g in fr:
            for h in list(Dset)[:50]:
                k = mul(g, h)
                if k not in Dset: Dset.add(k); nx.append(k)
        fr = nx
print('derived subgroup size (approx closure):', len(Dset), ' abelianisation order:', len(seen) // len(Dset))
# which words of length <= 6 in T, C, C^-1 are relations
import itertools
alpha = {'T': T, 'C': C, 'c': inv(C)}
rels = []
for L in range(1, 9):
    for w in itertools.product('TCc', repeat=L):
        s = ''.join(w)
        if 'TT' in s or 'Cc' in s or 'cC' in s or 'CCC' in s or 'ccc' in s: continue
        m = E
        for ch in s: m = mul(m, alpha[ch])
        if m == E: rels.append(s)
print('short relators (reduced, length <= 8):', rels[:20], '... total', len(rels))
